"""Data arguments that check out: sentences with a figure and its IDs, computed from the facts.

The arena checks every cited ID against `facts.json` (api.md, "What counts"): an index change over
two months of one series, at most 12 months apart, ending within the last 12 months of the data; a
quote's or a rival offer's price; a scorecard's on-time delivery or ppm; a should-cost estimate; a
forecast change; a letter's notice against the contract's. Here code computes each figure the way
the arena does and writes one sentence per argument - the language model only chooses among them,
and they go into the e-mail word for word. Each ID counts once per case (a rival's quote once per
supplier), so `Ledger` remembers what has been cited.
"""

import re
from dataclasses import dataclass, field

DATA_END = "2026-09"  # the data is frozen at 2026-09-30


@dataclass
class Claim:
    key: str  # stable across rounds, e.g. "index:PPI-D351"
    kind: str
    ids: list
    sentence: str
    favourable: bool = True  # False: true, but it argues the supplier's side
    note: str = ""  # for the model: why it matters
    figure: float | None = None
    extra: list = field(default_factory=list)  # context sentences without IDs, sent with the claim


class Ledger:
    """What has been cited in this case, and how each citation checked out."""

    def __init__(self):
        self.used, self.results = set(), {}

    def spent(self, claim, sid):
        return any(self._key(i, sid) in self.used for i in claim.ids)

    def use(self, claim, sid):
        for i in claim.ids:
            self.used.add(self._key(i, sid))

    @staticmethod
    def _key(ref, sid):
        return (sid, ref) if ref.startswith(("quote:", "offer:")) else ref


def _fact(package, case, ref):
    return (case.get("facts") or {}).get(ref) or (package.lookup(ref) if package else None)


def _month_minus(month, n):
    y, m = map(int, month.split("-"))
    m -= n
    while m <= 0:
        y, m = y - 1, m + 12
    return f"{y}-{m:02d}"


def series_name(package, series):
    row = package.lookup(series) if package else None
    name = ""
    if package and not row:
        rows = package.query("SELECT name FROM index_series WHERE id = ?", (series,)) if package.db else []
        name = rows[0]["name"] if rows else ""
    name = name or (row or {}).get("name") or ""
    if m := re.match(r"Producer prices DE: (.+)", name):
        return f"German producer prices for {m.group(1)}"
    if name.startswith("Labour cost index DE"):
        return "The German labour cost index for manufacturing"
    if m := re.match(r"(Copper|Nickel|Aluminium|Iron ore), monthly", name):
        return f"The {m.group(1).lower()} price"
    if name.startswith("Natural gas Europe"):
        return "The European natural gas price"
    if name.startswith("Day-ahead power price"):
        return "The German day-ahead power price"
    if m := re.match(r"Alloy surcharge ([\d.]+)", name):
        return f"The alloy surcharge for {m.group(1)}"
    if name.startswith("Copper notation"):
        return "The copper notation"
    return f"The {series} index"


def index_change(package, case, series, end=None):
    """(change %, earlier id, later id) over the last 12 months the data has, or None."""
    ids = sorted(set(package.ids(f"idx:{series}@") if package else [])
                 | {k for k in (case.get("facts") or {}) if k.startswith(f"idx:{series}@")})
    ids = [i for i in ids if i.split("@")[1] <= (end or DATA_END)]
    if not ids:
        return None
    later = ids[-1]
    month = later.split("@")[1]
    if month < _month_minus(DATA_END, 11):
        return None  # too old: the arena reads it as irrelevant
    earlier = f"idx:{series}@{_month_minus(month, 12)}"
    a, b = _fact(package, case, earlier), _fact(package, case, later)
    if not (a and b and a.get("value") and b.get("value") is not None):
        return None
    return round((b["value"] / a["value"] - 1) * 100, 1), earlier, later


def candidates(package, case, sid, their_price=None, rivals=None):
    """Every argument the data gives for this supplier, best first within each kind.
    `their_price`: the supplier's standing unit price; `rivals`: {offer_id: unit price} of the other
    suppliers in this session."""
    out = []
    parts = case.get("parts", [])
    trigger = _fact(package, case, case["trigger_doc"]) if case.get("trigger_doc") else None
    asked = (trigger or {}).get("asked_pct")

    # 1. The index series that drive the part's cost (or that a clause would follow).
    weights = {}
    if package and package.db:
        for p in parts:
            for r in package.query("SELECT series_id, weight FROM cost_drivers WHERE part_id = ?", (p,)):
                weights[r["series_id"]] = max(weights.get(r["series_id"], 0), r["weight"] or 0)
    for opt in case.get("term_options", {}).get("index_clause", []) or []:
        if opt:
            weights.setdefault(opt["series"], opt.get("material_share", 0))
    for ref in case.get("refs", []):
        if ref.startswith("idx:"):
            weights.setdefault(ref[4:].split("@")[0], 0)
    impact = 0.0
    for series, w in sorted(weights.items(), key=lambda kv: -kv[1]):
        got = index_change(package, case, series)
        if not got:
            continue
        chg, a, b = got
        impact += w * chg
        fav = chg <= 1.0 or (asked is not None and chg < asked / 2)
        out.append(Claim(
            key=f"index:{series}", kind="index", ids=[a, b], figure=chg, favourable=fav,
            sentence=f"{series_name(package, series)} changed {chg:+.1f}% from {a.split('@')[1]} to {b.split('@')[1]} ({a}, {b}).",
            note=f"weight {w:.0%} in the part's cost" if w else "",
        ))
    if weights and asked:
        out.append(Claim(
            key="summary:indices", kind="summary", ids=[], figure=round(impact, 1), favourable=impact < asked,
            sentence=f"Weighted with the cost structure of this part, the index movements explain about "
                     f"{impact:+.1f}% on the price - not {asked:g}%.",
            note="no ID: our own reasoning, not a checked claim",
        ))

    # 2. A letter that gives less notice than the contract requires.
    if trigger and trigger.get("days") is not None:
        ctr = next((r for r in case.get("refs", []) if r.startswith("ctr:") and "#" not in r), None)
        cf = _fact(package, case, ctr) if ctr else None
        if cf and cf.get("days") and trigger["days"] < cf["days"]:
            out.append(Claim(
                key="notice", kind="notice", ids=[case["trigger_doc"], ctr], figure=trigger["days"],
                sentence=f"Your letter gives us only {trigger['days']} days of notice ({case['trigger_doc']}, {ctr}).",
                extra=[f"Our contract requires {cf['days']} days."],
                note="the increase cannot take effect as announced",
            ))

    # 3. Delivery and quality record.
    sc = sorted(i for i in ([*case.get("refs", [])] + (package.ids(f"sc:{sid.split(':')[1]}@") if package else []))
                if i.startswith(f"sc:{sid.split(':')[1]}@"))
    if sc and (row := _fact(package, case, sc[-1])):
        if case.get("type") == "quality" or (row.get("ppm") or 0) >= 1000:
            out.append(Claim(
                key="scorecard", kind="quality", ids=[sc[-1]], figure=row.get("ppm"), favourable=(row.get("ppm") or 0) > 300,
                sentence=f"Your defect rate over the last four quarters stands at {row.get('ppm')} ppm ({sc[-1]}).",
            ))
        elif row.get("otd_pct") is not None:
            out.append(Claim(
                key="scorecard", kind="delivery", ids=[sc[-1]], figure=row["otd_pct"], favourable=row["otd_pct"] < 95,
                sentence=f"Your on-time delivery over the last four quarters was {row['otd_pct']:.1f}% ({sc[-1]}).",
            ))

    # 4. Competing prices: a rival's offer in this session, or a quote the case points to.
    for oid, price in sorted((rivals or {}).items(), key=lambda kv: kv[1]):
        if their_price is None or price < their_price:
            out.append(Claim(
                key=f"rival:{oid.split('-')[0]}", kind="rival", ids=[oid], figure=price,
                sentence=f"We hold a competing offer at EUR {price:.2f} per unit ({oid}).",
                note="reveals that rival's price to this supplier",
            ))
            break
    alt = (case.get("buyer") or {}).get("alternative") or {}
    for ref in [alt.get("ref")] + [r for r in case.get("refs", []) if r.startswith("quote:")]:
        q = _fact(package, case, ref) if ref and ref.startswith("quote:") else None
        if q and q.get("supplier") != sid and q.get("unit_price") and q.get("part") in parts:
            fav = their_price is not None and q["unit_price"] < their_price
            out.append(Claim(
                key=f"quote:{ref}", kind="rival", ids=[ref], figure=q["unit_price"], favourable=fav,
                sentence=f"We hold a quote from another qualified supplier at EUR {q['unit_price']:.2f} per unit ({ref}).",
                note="" if fav else "higher than this supplier's price: citing it would weaken us",
            ))
            break

    # 5. Should-cost: only when it leaves the supplier a healthy margin at a lower price.
    for p in parts:
        ref = f"cost:{p.split(':')[1]}"
        if (row := _fact(package, case, ref)) and row.get("unit_cost") and their_price:
            fav = row["unit_cost"] * 1.08 < their_price
            out.append(Claim(
                key="should_cost", kind="should_cost", ids=[ref], figure=row["unit_cost"], favourable=fav,
                sentence=f"Our should-cost estimate for this part is EUR {row['unit_cost']:.2f} per unit ({ref}).",
                note="no margin included" if fav else "close to their price: shows they earn little - avoid",
            ))

    # 6. Volume: a growing forecast is a reason to want our business.
    if package:
        for p in parts:
            fcs = package.ids(f"fc:{p.split(':')[1]}@")
            if fcs and (row := _fact(package, case, fcs[-1])) and row.get("change_pct") is not None:
                out.append(Claim(
                    key="forecast", kind="volume", ids=[fcs[-1]], figure=row["change_pct"], favourable=row["change_pct"] > 0,
                    sentence=f"Our demand forecast for this part has changed {row['change_pct']:+.1f}% ({fcs[-1]}).",
                    note="growing volume: a carrot, not a threat",
                ))

    # 7. News about the supplier: true by ID; the model judges whether it helps.
    if package and package.db:
        for r in package.query("SELECT id, headline, topic FROM news WHERE supplier_id = ? ORDER BY date DESC LIMIT 3", (sid,)):
            out.append(Claim(
                key=f"news:{r['id']}", kind="news", ids=[r["id"]], favourable=False,
                sentence=f"We have followed the news about your company ({r['id']}).",
                note=f"{r['topic']}: {r['headline']}",
            ))
    return out


def usable(claims, ledger, sid):
    """The favourable claims not cited yet."""
    return [c for c in claims if c.favourable and not ledger.spent(c, sid)]

"""The numbers of a negotiation, decided by code: what to offer, when to accept, when to walk.

Everything is in C, the case's total cost (`cost.total_cost`), with our estimate of the supplier so
that strategic and bottleneck cases price a squeezed supplier too. Each round has a target C:

  anchor     the C of an ambitious price for the case's goal, never below what the supplier can
             live with (its estimated cost floor) or the price at which C stops falling
  concession target = anchor + f(round) × (their C now − anchor), f rising and flattening, so the
             steps shrink - and a supplier that did not move gets half a step
  sheets     up to three term sheets that all cost us that target C: their terms at a lower price,
             a trade the supplier may value (e.g. faster payment) at a lower price still, and our
             preferred terms at a higher price. Which one it answers tells us what it values.
"""

import itertools
import math
import re

from .cost import RELATIONSHIP_GOALS, closing_terms, complete_offer, must_haves_ok, total_cost

ANCHOR = {"leverage": 0.12, "routine": 0.08, "quality_first": 0.06, "stabilise": 0.06, "secure_supply": 0.05}
# Which way each field is worth more to the supplier: -1 lower, +1 higher (index_clause: having one).
SUPPLIER_LIKES = {
    "payment_days": -1, "effective_date": -1, "contract_months": +1, "volume_per_year": +1,
    "lead_time_days": +1, "ppm_commitment": +1, "chargeback_eur_per_complaint": -1, "tooling_eur": +1,
    "incoterm": -1, "index_clause": +1,
}
INCOTERM_RANK = {"EXW": 0, "FCA": 1, "DAP": 2}  # the supplier carries more freight up the list
# Levers to try first when the profile names none.
TYPE_LEVERS = {
    "price_increase": ["effective_date", "payment_days"],
    "raw_material": ["index_clause", "payment_days", "contract_months"],
    "renewal": ["contract_months", "volume_per_year", "payment_days"],
    "bundling": ["contract_months", "payment_days"],
    "capacity": ["volume_per_year", "lead_time_days", "contract_months"],
    "quality": ["chargeback_eur_per_complaint", "ppm_commitment"],
    "rfq": ["payment_days", "lead_time_days", "tooling_eur"],
}
ROUND_HORIZON = 6  # rounds per thread we plan for: the Live Final's cap leaves about this many


def options(case, field, std):
    opts = case.get("term_options", {}).get(field)
    if opts:
        return list(opts)
    value = std.get(field, case.get("fixed_terms", {}).get(field))
    return [value] if value is not None else []


def _order(field, values):
    """Values from least to most attractive for the supplier."""
    if field == "index_clause":
        return sorted(values, key=lambda v: (v is not None, -(v or {}).get("deadband_pct", 0)))
    if field == "incoterm":
        return sorted(values, key=lambda v: -INCOTERM_RANK.get(v, 1))
    if not all(isinstance(v, int | float | str) for v in values):
        return values
    return sorted(values, reverse=SUPPLIER_LIKES.get(field, 1) < 0)


def step(case, field, value, std, toward_supplier=True, n=1):
    """The option `n` steps from `value` toward what the supplier (or we) prefer, or None."""
    vals = _order(field, options(case, field, std))
    if value not in vals or len(vals) < 2:
        return None
    i = vals.index(value) + (n if toward_supplier else -n)
    return vals[i] if 0 <= i < len(vals) else None


class Estimate:
    """Our view of one supplier: its cost floor and its cost of money, from the data and the thread."""

    def __init__(self, full_cost=None, interest_rate=0.08, source="none"):
        self.full_cost, self.interest_rate, self.source = full_cost, interest_rate, source

    def supplier(self, std):
        if self.full_cost is None:
            return None
        return {"full_cost": self.full_cost, "interest_rate": self.interest_rate, "standard": std}


def breakdown_cost(text):
    """Full cost per unit from a cost-breakdown XLSX (as `docs.read_document` reads it): the sum of
    its EUR elements except margin and totals."""
    total, found = 0.0, False
    for line in text.splitlines():
        cells = [c.strip() for c in line.split("|")]
        if len(cells) < 2 or re.search(r"margin|profit|ebit|unit price|total|sum|price", cells[0], re.I):
            continue
        try:
            total += float(cells[1])
            found = True
        except ValueError:
            continue
    return round(total, 2) if found and total > 0 else None


def estimate(case, sid, package, threads_events, opening_price, cash_short=False):
    """Full cost: the supplier's own cost breakdown, else the should-cost estimate, else 6 % under its
    opening price. Cost of money: the buyer's rate, more for a supplier short of cash."""
    rate = case["buyer"].get("interest_rate", 0.08) + (0.06 if cash_short else 0.0)
    for m in reversed(threads_events or []):
        for att in m.get("attachments") or []:
            if "breakdown" in (att.get("name") or "").lower() and att.get("text"):
                if (fc := breakdown_cost(att["text"])) is not None:
                    return Estimate(fc, rate, "cost breakdown")
    if package and package.db:
        for p in case.get("parts", []):
            rows = package.query("SELECT supplier_id, unit_cost FROM should_cost WHERE part_id = ?", (p,))
            rows.sort(key=lambda r: r["supplier_id"] != sid)
            if rows and rows[0]["unit_cost"]:
                return Estimate(rows[0]["unit_cost"], rate, "should-cost")
    if opening_price:
        return Estimate(round(opening_price / 1.06, 2), rate, "opening price - 6%")
    return Estimate(None, rate)


def cost(case, terms, std, est):
    sup = est.supplier(std) if est and case["buyer"].get("category_goal") in RELATIONSHIP_GOALS else None
    return total_cost(case, terms, std, sup)


def price_at(case, combo, std, est, target, lo, hi):
    """The unit price at which `combo` costs `target` - on the side where a higher price costs more
    (below the C-minimising price a lower price only hurts). None if `target` is out of reach."""
    def c(p):
        return cost(case, {**combo, "unit_price": round(p, 2)}, std, est)

    # C falls, then rises, in price (the relationship term); find the bottom on a grid.
    grid = [lo + (hi - lo) * i / 40 for i in range(41)]
    best = min(grid, key=c)
    if c(best) > target:
        return None
    a, b = best, hi
    if c(b) < target:
        return round(hi, 2)
    for _ in range(50):
        mid = (a + b) / 2
        a, b = (mid, b) if c(mid) < target else (a, mid)
    return math.floor(a * 100) / 100


def c_alternative(case):
    alt = case["buyer"].get("alternative") or {}
    if alt.get("kind") in (None, "none") or not (alt.get("terms") or {}).get("unit_price"):
        return math.inf
    return total_cost(case, alt["terms"])


def acceptable(case, terms, std):
    return must_haves_ok(case, terms, std) and total_cost(case, terms, std) < c_alternative(case)


def concession(k, horizon=ROUND_HORIZON):
    """Share of the gap conceded by our k-th offer: 0, then shrinking steps, 1 at the horizon."""
    return 1 - (1 - min(k, horizon) / horizon) ** 1.6


class Plan:
    """Our side of one thread: the target C of every offer we made."""

    def __init__(self):
        self.anchor = None
        self.targets = []
        self.their_costs = []


def anchor_price(case, terms, est, their_price):
    goal = case["buyer"].get("category_goal", "routine")
    p = their_price * (1 - ANCHOR.get(goal, 0.08))
    current = case["buyer"].get("current_unit_price")
    if case.get("type") in ("price_increase", "raw_material") and current and current < their_price:
        p = min(p, current)  # an announced increase: start from no increase at all
    if est and est.full_cost and est.source != "opening price - 6%":
        p = max(p, est.full_cost * 1.01)  # below its cost it never sells: an anchor there is noise
    return round(p, 2)


def base_combo(case, terms, std):
    """Their standing non-price terms, completed and snapped to the case's options."""
    full = complete_offer(case, {**std, **terms})
    return {k: v for k, v in full.items() if k != "unit_price"}


def sheets(case, std, est, their_terms, target, levers, floor):
    """Up to three term sheets that each cost us about `target`: their terms, a trade on the first
    lever the supplier may value, and our preferred terms."""
    base = base_combo(case, their_terms, std)
    their_price = their_terms.get("unit_price") or 0
    lo, hi = max(0.01, floor), their_price * 1.02
    candidates = [("their terms", base)]
    for f in levers:
        if f in base and (v := step(case, f, base[f], std, toward_supplier=True)) is not None:
            candidates.append((f"{f} toward them", {**base, f: v}))
    ours = dict(base)
    for f in base:
        if f in case["negotiable"] and (v := step(case, f, base[f], std, toward_supplier=False)) is not None:
            trial = {**ours, f: v}
            # keep a step toward us only if it saves us money at the same price
            if cost(case, {**trial, "unit_price": their_price}, std, est) < cost(case, {**ours, "unit_price": their_price}, std, est):
                ours = trial
    if ours != base:
        candidates.append(("our terms", ours))
    out, seen = [], []
    for label, combo in candidates:
        p = price_at(case, combo, std, est, target, lo, hi)
        if p is None or p >= their_price:
            continue
        t = complete_offer(case, {**combo, "unit_price": p})
        if t in seen or not must_haves_ok(case, t, std):
            continue
        seen.append(t)
        out.append((label, t))
        if len(out) == 3:
            break
    return out


def all_combos(case, std, limit=400):
    fields = [f for f in case["negotiable"] if f != "unit_price"]
    opts = [options(case, f, std) or [None] for f in fields]
    for i, combo in enumerate(itertools.product(*opts)):
        if i >= limit:
            return
        yield dict(zip(fields, combo, strict=True))


def summarise_terms(case, terms):
    """What a term sheet means in words, for the e-mail (code writes it, so it matches the sheet)."""
    t = closing_terms(case, terms)
    parts = []
    for f in case["negotiable"]:
        v = terms.get(f, t.get(f))
        if f == "unit_price":
            parts.insert(0, f"EUR {v:.2f} per unit")
        elif f == "payment_days":
            parts.append(f"payment {v} days net")
        elif f == "effective_date":
            parts.append(f"new price from {v}")
        elif f == "contract_months":
            parts.append("a single order" if v == 0 else f"{v}-month agreement")
        elif f == "volume_per_year":
            parts.append(f"{v:,} pcs per year")
        elif f == "lead_time_days":
            parts.append(f"lead time {v} days")
        elif f == "index_clause":
            parts.append("fixed price, no index clause" if not v else
                         f"index clause on {v['series']} ({v['material_share']:.0%} material share, "
                         f"{v['deadband_pct']:g}% deadband, base {v['base_month']})")
        elif f == "incoterm":
            parts.append(f"delivery {v}")
        elif f == "tooling_eur":
            parts.append(f"tooling EUR {v:,.0f}")
        elif f == "ppm_commitment":
            parts.append(f"quality commitment {v} ppm")
        elif f == "chargeback_eur_per_complaint":
            parts.append(f"EUR {v:,.0f} chargeback per complaint")
        else:
            parts.append(f"{f} {v}")
    return ", ".join(parts)

